<?php defined('BASEPATH') or exit('No direct script access allowed');$fileEscape=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');$fc=$project_file_controls;$fileHidden=function($action,$receipt=null)use($fileEscape,$portal_csrf,$project_file_parent,$fc){foreach(['action'=>$action,'portal_csrf'=>$portal_csrf,'project_id'=>$project_file_parent,'project_revision'=>$fc['project_revision'],'file_collection_revision'=>$fc['collection_revision'],'request_key'=>bin2hex(random_bytes(32))] as $field=>$value)echo '<input type="hidden" name="'.$fileEscape($field).'" value="'.$fileEscape($value).'">';if($receipt!==null)echo '<input type="hidden" name="file_receipt_key" value="'.$fileEscape($receipt).'">';}; ?>
<section id="portal-project-contact-files"><h2>Seus arquivos do projeto</h2><p>O envio fica privado para você e a equipe deste projeto. Outros contatos não recebem o nome nem o conteúdo até uma publicação explícita pela equipe. PDF até 2 MiB; PNG/JPEG até 512 KiB e 1600 pixels, normalizado como PNG. Limite de 20 arquivos e 20 MiB no histórico do projeto, incluindo ocultos.</p>
<?php if($fc['can_upload']){echo form_open_multipart($url,['id'=>'portal-project-file-upload']);$fileHidden('project_contact_file_upload'); ?><label for="portal-project-file-input">Arquivo do projeto</label><input type="file" id="portal-project-file-input" name="operation_file" accept=".pdf,.png,.jpg,.jpeg" required><button type="submit">Enviar arquivo privado ao projeto</button><?= form_close(); ?><?php }else{ ?><p>Novos envios não estão autorizados neste projeto. Os arquivos publicados pela equipe continuam disponíveis no pacote autorizado.</p><?php } ?>
<ul id="portal-project-own-files"><?php foreach($fc['items'] as $item){ ?><li><a href="<?= $fileEscape($url.'?operation_kind=projects&resource_id='.$project_file_parent.'&project_file_receipt='.$item['request_key']); ?>"><?= $fileEscape($item['filename']); ?></a> · <?= $item['active']?'Ativo':'Oculto'; ?> · <?= $fileEscape($item['created_at']); ?></li><?php } ?></ul>
<?= form_open($url,['id'=>'portal-project-files-bundle']);$fileHidden('project_contact_files_bundle'); ?><p>O ZIP inclui apenas seus arquivos privados ativos e os arquivos ativos publicados pela equipe para os contatos deste cliente. Nomes originais e hashes ficam em manifesto.json; os anexos têm nomes de arquivo seguros no pacote.</p><button type="submit">Baixar arquivos autorizados em ZIP</button><?= form_close(); ?>
<?php if(is_array($project_file_receipt??null)){$result=$project_file_receipt;$evidence=$result['receipt']; ?><article id="portal-project-file-result"><h3>Resultado privado do envio</h3><p><?= $evidence['operation']==='upload'?'Arquivo recebido e preservado.':'Arquivo oculto; histórico preservado.'; ?> <?= $result['public_current']?'A equipe publicou este arquivo para os contatos autorizados do cliente.':'Este resultado permanece privado para você e a equipe.'; ?></p><dl><dt>Arquivo</dt><dd><?= $fileEscape($evidence['data']['filename']); ?></dd><dt>Autor registrado</dt><dd><?= $fileEscape($evidence['author_name']); ?></dd><dt>Data</dt><dd><?= $fileEscape($result['created_at']); ?></dd><dt>SHA-256 registrado</dt><dd><?= $fileEscape($evidence['data']['content_hash']); ?></dd></dl>
<?php if($result['file_available']){echo form_open($url,['id'=>'portal-project-file-author-download']);$fileHidden('project_contact_file_download',$result['request_key']); ?><button type="submit">Baixar seu arquivo privado</button><?= form_close(); ?><?php }else{ ?><p>Este resultado não oferece bytes de arquivo ativos.</p><?php }if($result['can_hide']){echo form_open($url,['id'=>'portal-project-file-hide']);$fileHidden('project_contact_file_hide'); ?><input type="hidden" name="file_key" value="<?= $fileEscape($evidence['file_key']); ?>"><button type="submit">Excluir meu arquivo e preservar histórico</button><?= form_close(); ?><?php } ?></article><?php } ?></section>
